    34  #include <assert.h>
    35  #include <errno.h>
    36  #include <gelf.h>
    37  #include <stddef.h>
    38  #include <unistd.h>
    39
    40  #include <system.h>
    41  #include "libelfP.h"
    42  #include "common.h"
